<?php use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Facades\Hash; uses(RefreshDatabase::class); it('registers and logs in',function(){ $r=$this->postJson('/api/v1/auth/register',['name'=>'Test','email'=>'test@example.com','password'=>'password','password_confirmation'=>'password','role'=>'owner']);$r->assertCreated()->assertJsonStructure(['token','user']);$this->postJson('/api/v1/auth/login',['email'=>'test@example.com','password'=>'password'])->assertOk()->assertJsonStructure(['token']);}); it('prevents cross owner pet access',function(){ $a=User::factory()->create(['role'=>'owner']);$b=User::factory()->create(['role'=>'owner']);$pet=$a->pets()->create(['name'=>'A','species'=>'Dog']);$this->actingAs($b,'sanctum')->getJson('/api/v1/pets/'.$pet->id)->assertForbidden();});
